                result.score.isFinite, result.nominate == (result.score > utility.margin) else {
                throw Failure(check: "utility435-finite-source-model-evaluation")
            }
            utilityChecks += 1
        }
        guard utilityChecks > 0 else { throw Failure(check: "utility435-nonempty-source-controls") }
        config.families = ["source-utility435-all8-select"]
        guard config.requestsSourceUtility435All8 && config.requestsSourceUtility435 &&
            config.requestsRawRegression435 && !config.requestsMeanRegression435 &&
