        }
        return ["status": "pass", "authenticInputs": fixtures.count,
            "utility435SourceModelControls": utilityChecks,
            "utility435DefaultOffAnd433BaselineRetained": true,
            "all8Utility435ModelAndCascadeControls": true,
            "maximumPythonFeatureAbsDifference": maximumFeatureError,
            "actualSwiftGeometryAuthoritative": true, "actualSwiftGeometrySnapshots": snapshots,
            "modelSHA256": SourceBoundaryRegression435Calibration.frozenBundleSHA256,
            "nativeAdmissionNotSimulated": true, "GGMaskOrMeasurementFabricated": false,
            "detectorCalls": 0, "recognizerCalls": 0, "GTRead": false]
    }
